'use client'

import * as React from 'react'

import { useStrings, type StringsOverrides } from './strings'
import { TriangleGlyph } from './glyphs'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Vote, and `tsc --noEmit` passes on it, so the
// gate cannot catch it.
import './vote.css'

// The shared rule sets, so the theme's action face and press gesture reach the
// control. GSUI-118: the file shipped with the tokens and nothing imported it,
// so the classes matched nothing in a real install.
import './gamestage-primitives.css'

/**
 * Vote: a message the room can push up.
 *
 * Specimen 6e. One control carrying its own count, so there is no second
 * number to read anywhere in the row and nothing to keep in step. The press
 * that casts a vote is the press that takes it back, which is why the control
 * keeps its shape, its width and its place: a control that turned into a
 * figure once pressed would move the next message under the reader's thumb.
 *
 * Three states, and two of them are independent. `voted` is the reader's own
 * press. `top` is the room's: the message has passed a threshold the host
 * sets, and a reader who never voted still sees it. A message can carry both,
 * either or neither.
 *
 * It ranks nothing and counts nothing. The count is a prop, the threshold is
 * the host's, and the optimistic tick by one on a press is the host
 * re-rendering with a larger number rather than this component guessing.
 */

export interface VoteProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'onChange'> {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides

  /** How many people have pushed this message up. Host-owned. */
  count?: number
  /** The reader's vote is on this message. The same press takes it back. */
  voted?: boolean
  /**
   * The room's top message, at a threshold the host sets. One at a time, or
   * the room turns gold.
   */
  top?: boolean
  /** The control was pressed. Casting and taking back are the same press. */
  onVote?: () => void
}

export function Vote(props: VoteProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)

  const {
    count = 0,
    voted = false,
    top = false,
    onVote,
    className,
    onClick,
    ...rest
  } = componentProps

  // Every state is in the name, because a screen reader user gets no fill and
  // no stroke. The count is read with it: the control is the only place the
  // number appears, so a name without it would leave the number unreadable.
  const stateWords = [voted ? copy['vote.voted'] : undefined, top ? copy['vote.top'] : undefined]
    .filter(Boolean)
    .join(', ')

  return (
    <button
      {...rest}
      type="button"
      className={['gs-vote', 'gs-action-type', 'gs-pressable', className].filter(Boolean).join(' ')}
      data-gs-component="vote"
      data-gs-count={count}
      data-gs-voted={voted ? 'true' : undefined}
      data-gs-top={top ? 'true' : undefined}
      // The press is a toggle, so the control says so rather than leaving a
      // reader to work out that pressing again undoes it.
      aria-pressed={voted}
      aria-label={
        stateWords === ''
          ? copy['vote.label'](count)
          : copy['vote.labelState'](copy['vote.label'](count), stateWords)
      }
      onClick={event => {
        onClick?.(event)
        onVote?.()
      }}
    >
      <span className="gs-vote__glyph" data-gs-scope="vote" data-gs-part="glyph" aria-hidden="true">
        <TriangleGlyph />
      </span>
      <span className="gs-vote__count" data-gs-scope="vote" data-gs-part="value" aria-hidden="true">
        {count}
      </span>
    </button>
  )
}

/* Vote. Every value comes from a token; nothing here is a literal colour.

   Specimen 6e draws a 44px pill on the end of a message row, glyph then count,
   with the pressable depth under it. The control keeps its width class in all
   three states: the fill changes, the stroke changes, the number changes, and
   nothing about the box does, because taking a vote back is the same press and
   a row that resized on a press would move the next message. */

.gs-vote {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-1);
  box-sizing: border-box;
  height: var(--gs-size-touch-min);
  padding: 0 var(--gs-space-2);
  cursor: pointer;

  /* The count is read at a glance beside a bubble of body text, so it takes
     the figure face rather than the body one. */
  font-variant-numeric: tabular-nums;

  color: var(--gs-color-ink-secondary);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  box-shadow: var(--gs-depth-raised);
  transition:
    background var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis),
    color var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis),
    border-color var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

.gs-vote__glyph {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: var(--gs-size-icon-utility);
  height: var(--gs-size-icon-utility);
}

.gs-vote__count {
  font-family: var(--gs-type-figure-font-family);
  font-weight: var(--gs-type-figure-font-weight);
  line-height: 1;
}

/* -- voted ------------------------------------------------------------------

   The fill is the change a sighted player reads, and the accessible name and
   aria-pressed are the change everybody else reads. The count is already one
   higher because the host handed back a larger number. */

.gs-vote[data-gs-voted='true'] {
  color: var(--gs-color-on-bright);
  background: var(--gs-color-positive);
  border-color: var(--gs-color-edge);
}

/* -- top message ------------------------------------------------------------

   The room's own state rather than the reader's, so it is drawn in the reward
   colour and it outranks the reader's fill: a top message the reader also
   voted for is still the top message first. One at a time is the host's rule
   and this component does not enforce it, because it is shown one control and
   knows nothing about the others. */

.gs-vote[data-gs-top='true'] {
  color: var(--gs-color-on-bright);
  background: var(--gs-color-reward);
  border-color: var(--gs-color-reward-base);
}
